"""Task-oriented help; saved conditions remain the source of selection truth."""

def explain_rule(rule):
    from .engine import METRICS
    module = rule.settings.module
    metric = rule.metric
    value = rule.value
    shown = '، '.join(str(v) for v in value) if isinstance(value, list) else str(value)
    label = METRICS[module].get(metric, (metric,))[0].split('؛')[0]
    comparisons = {'eq': 'برابر با', 'ne': 'متفاوت از', 'gt': 'بیشتر از', 'gte': 'حداقل', 'lt': 'کمتر از', 'lte': 'حداکثر'}
    if rule.operator == 'in':
        why = f'{label} در CRM یکی از این مقدارهاست: {shown}.'
    elif rule.operator == 'contains_any':
        why = f'در {label} یکی از عبارت‌های «{shown}» آمده است.'
    elif isinstance(value, bool):
        positive = value if rule.operator == 'eq' else not value
        descriptions = {
            'has_parent': ('کیس به یک برنامه مرتبط شده است.', 'برای کیس، برنامه مرتبطی در اطلاعات دریافتی مشخص نشده است.'),
            'no_note': ('در یادداشت‌های دریافت‌شده، گزارشی برای این مورد پیدا نشده است.', 'برای این مورد یادداشت دریافت شده است.'),
            'manager_missing': ('نام مدیر پروژه در اطلاعات دریافتی خالی است.', 'نام مدیر پروژه در اطلاعات دریافتی وجود دارد.'),
            'planned_end_missing': ('تاریخ پایان برنامه‌ریزی‌شده پروژه در اطلاعات دریافتی خالی است.', 'تاریخ پایان برنامه‌ریزی‌شده پروژه ثبت شده است.'),
        }
        why = descriptions.get(metric, (f'{label}: بله.', f'{label}: خیر.'))[0 if positive else 1]
    else:
        comparator = comparisons.get(rule.operator, rule.operator)
        if metric == 'note_age':
            why = f'از آخرین ویرایش یادداشت دریافت‌شده {comparator} «{shown}» روز گذشته است.'
        elif metric == 'overdue_days':
            target = 'پایان پروژه' if module == 'projects' else 'یکی از اقدام‌های باز این کیس'
            why = f'فاصله امروز با موعد {target} {comparator} «{shown}» روز است؛ عدد مثبت یعنی موعد گذشته است.'
        else:
            why = f'{label} {comparator} «{shown}» است.'

    guidance = {
        'has_parent': ('بررسی کنید این کیس باید در کدام برنامه مشتری پیگیری شود. اگر ارتباط اشتباه یا خالی است، اصلاح آن را در CRM پیگیری کنید.', 'روشن می‌شود چه کیس‌هایی را می‌توان در یک برنامه مشترک پیگیری کرد.'),
        'parent_status': ('وضعیت برنامه مرتبط را با کار باقی‌مانده این کیس مقایسه کنید؛ مشخص کنید کیس هنوز به همان برنامه وابسته است یا پیگیری جدا می‌خواهد.', 'از باقی‌ماندن کیس زیر برنامه‌ای با وضعیت نامتناسب جلوگیری می‌شود.'),
        'source_status': ('آخرین توضیح کارشناس و نتیجه پیگیری مشتری را بخوانید و قدم بعدی کیس را مشخص کنید.', 'مشخص می‌شود کیس به ادامه کار، هماهنگی یا تأیید نتیجه نیاز دارد.'),
        'fix_newer': ('نگارش فعلی مشتری را با نگارش رفع کیس و مقصد ارتقا تطبیق دهید؛ آمادگی نصب و نتیجه هر کیس را جداگانه بررسی کنید.', 'کیس‌های دارای رفع ثبت‌شده در نگارش جدیدتر مشخص می‌شوند؛ این شمارش تضمین بسته‌شدن کیس نیست.'),
        'parent_title': ('کیس‌های زیر این برنامه را مرور کنید و مشخص کنید کدام‌یک واقعاً کار مشترک دارند.', 'پیگیری‌های مرتبط در یک برنامه اجرایی جمع می‌شوند.'),
        'title': ('شرح کامل کیس و آخرین پیگیری را بخوانید؛ عنوان به‌تنهایی برای تصمیم کافی نیست.', 'اقدام بعدی بر اساس مسئله واقعی تعیین می‌شود.'),
        'note_age': ('از مسئول مربوط بخواهید آخرین وضعیت، مانع و قدم بعدی را روشن کند. ابتدا بررسی کنید گزارش تازه‌ای خارج از فهرست دریافتی وجود نداشته باشد.', 'تصمیم شما بر اساس وضعیت تازه گرفته می‌شود؛ قدیمی‌بودن یادداشت به معنی انجام‌نشدن کار نیست.'),
        'no_note': ('ابتدا وجود گزارش در CRM و تنظیم دریافت یادداشت‌ها را بررسی کنید؛ اگر گزارشی ثبت نشده، از مسئول مربوط گزارش وضعیت بخواهید.', 'مشخص می‌شود مشکل از دریافت اطلاعات است یا ثبت‌نشدن گزارش.'),
        'open_count': ('اقدام‌های ثبت‌شده و پیگیری‌های CRM را مرور کنید؛ در صورت نیاز، قدم بعدی را با مسئول و موعد مشخص ثبت کنید.', 'پیگیری بعدی روشن می‌شود. این شمارش فقط اقدام‌های باز همین برنامه را در بر می‌گیرد.'),
        'overdue_days': ('با مسئول کار، وضعیت فعلی و علت نرسیدن به موعد را بررسی کنید؛ برای کار باقی‌مانده مسئول و موعد واقع‌بینانه تعیین کنید.', 'کار عقب‌افتاده مسیر پیگیری روشن پیدا می‌کند؛ گذشتن موعد به‌تنهایی علت تأخیر را نشان نمی‌دهد.'),
        'blocker_count': ('شرح مانع اقدام را بخوانید و مشخص کنید رفع آن به تصمیم یا همکاری چه کسی نیاز دارد؛ برای رفع مانع مسئول و موعد بگذارید.', 'کار متوقف‌شده امکان ادامه پیدا می‌کند.'),
        'manager_missing': ('نام مسئول پروژه را با CRM تطبیق دهید و در صورت خالی‌بودن، تعیین و ثبت مدیر پروژه را پیگیری کنید.', 'معلوم می‌شود گزارش و تصمیم‌های پروژه را از چه کسی باید پیگیری کرد.'),
        'planned_end_missing': ('با مدیر پروژه درباره کار باقی‌مانده و تاریخ پایان قابل تعهد توافق کنید و ثبت آن را در CRM پیگیری کنید.', 'پیشرفت پروژه نسبت به یک موعد مشخص قابل پیگیری می‌شود.'),
        'status': ('وضعیت ثبت‌شده پروژه را با آخرین گزارش مدیر پروژه مقایسه کنید و کار باقی‌مانده را مشخص کنید.', 'وضعیت گزارش‌شده و برنامه ادامه کار با هم هماهنگ می‌شوند.'),
        'phase': ('از مدیر پروژه بپرسید برای پایان این مرحله چه کار یا تأییدی باقی مانده و مسئول آن کیست.', 'پیش‌نیاز ورود به مرحله بعد روشن می‌شود.'),
    }
    action, effect = guidance.get(metric, ('اطلاعات این مورد را با مسئول آن مرور و قدم بعدی را مشخص کنید.', 'مسیر پیگیری مشخص می‌شود.'))
    # Only explain Done specially when the saved condition actually selects Done alone.
    if metric == 'source_status' and rule.operator == 'in' and isinstance(value, list) and [str(v).strip().casefold() for v in value] == ['done']:
        why = 'وضعیت این کیس در CRM روی Done است. این وضعیت به‌تنهایی نشان نمی‌دهد مشکل در محیط مشتری برطرف شده است.'
        action = 'بررسی کنید چه کاری برای رفع مشکل انجام شده، آیا نتیجه در محیط مشتری بررسی شده و آیا مشتری رفع مشکل را تأیید کرده است. اگر رفع به ارتقای نسخه وابسته است، نصب نسخه لازم را هم پیگیری کنید.'
        effect = 'اگر رفع مشکل تأیید شد، بستن کیس را در CRM پیگیری کنید؛ در غیر این صورت، اقدام باقی‌مانده را با مسئول و موعد ثبت کنید.'
    if rule.purpose == 'opportunity':
        group = 'یک مرکز و یک برنامه مشترک' if rule.grouping == 'customer_program' else 'یک مرکز، حتی در چند برنامه'
        why += f' حداقل {rule.min_count} کیس با این ویژگی در {group} قرار دارند.'
        action = f'{rule.action_title or rule.label}. پیش از هماهنگی، فهرست کیس‌ها را مرور کنید و مطمئن شوید همین اقدام برای آن‌ها کاربرد دارد؛ سپس مسئول و زمان اجرا را تعیین کنید.'
        effect = (rule.impact or 'چند کیس مرتبط با هماهنگی مشترک پیگیری می‌شوند.') + ' پس از اجرا، نتیجه هر کیس را جدا بررسی کنید؛ تعداد نمایش‌داده‌شده تضمین نمی‌کند همه کیس‌ها بسته شوند.'
    parts = [f'چرا این موارد نمایش داده می‌شوند؟\n{why}', f'چه کاری انجام دهید؟\n{action}', f'چه کمکی می‌کند؟\n{effect}']
    if rule.active_only:
        parts.append('دامنه بررسی: فقط مواردی که در آخرین اطلاعات دریافتی هنوز جاری هستند. موارد با وضعیت نامعلوم نیاز به بررسی جدا دارند.')
    if metric in ('note_age', 'no_note'):
        parts.append('مبنای گزارش، یادداشت‌های دریافت‌شده است. اگر یادداشت‌ها هنوز دریافت نشده‌اند، این معیار قابل بررسی نیست.')
    return '\n\n'.join(parts)
